    INSERT INTO `sys_biz_config` VALUES (1,'sales','sales.order.auto_no','销售订单号自动生成','开启后，创建订单时自动生成订单号；关闭后需手动填写','switch',NULL,'true',NULL,10,NULL,NULL,'2026-03-02 16:36:02',0),(2,'sales','sales.order.no_rule','订单号生成规则','自动生成订单号时采用的格式规则','radio','[{\"label\": \"日期+随机数\", \"value\": \"date_random\"}, {\"label\": \"日期+流水号\", \"value\": \"date_seq\"}, {\"label\": \"自定义前缀+流水号\", \"value\": \"prefix_seq\"}]','date_random','date_seq',20,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(3,'sales','sales.delivery.check_stock','发货时检查库存','开启后，发货时将检查库存是否充足；关闭后不校验库存直接发货','switch',NULL,'true',NULL,30,NULL,NULL,'2026-03-02 16:36:02',0),(4,'sales','sales.order.product_source','订单产品来源','配置销售订单中产品的来源方式','radio','[{\"label\": \"物料信息\", \"value\": \"material\"}, {\"label\": \"物料分类\", \"value\": \"category\"}]','material',NULL,40,NULL,NULL,'2026-03-02 16:36:02',0),(5,'sales','sales.delivery.allow_overdue','允许超期发货','开启后，允许在交货期后仍进行发货操作','switch',NULL,'false','true',50,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(6,'sales','sales.quotation.valid_days','报价单有效期（天）','报价单默认有效天数，0表示永久有效','number',NULL,'30',NULL,60,NULL,NULL,'2026-03-02 16:36:02',0),(7,'purchase','purchase.order.auto_no','采购订单号自动生成','开启后自动生成采购订单号','switch',NULL,'true',NULL,10,NULL,NULL,'2026-03-02 16:36:02',0),(8,'purchase','purchase.request.need_approval','采购申请需要审批','开启后，采购申请提交后须经审批才可转为采购订单','switch',NULL,'true',NULL,20,NULL,NULL,'2026-03-02 16:36:02',0),(9,'purchase','purchase.receipt.need_inspection','到货需要质检','开启后，采购到货须进行质检才可入库','switch',NULL,'false',NULL,30,NULL,NULL,'2026-03-02 16:36:02',0),(10,'purchase','purchase.receipt.over_ratio','允许超额收货比例（%）','允许实收数量超出订单数量的最大比例，0表示不允许超收','number',NULL,'0',NULL,40,NULL,NULL,'2026-03-02 16:36:02',0),(11,'purchase','purchase.receipt.allow_partial','允许部分到货','开启后，一张采购订单可以分多次到货','switch',NULL,'true',NULL,50,NULL,NULL,'2026-03-02 16:36:02',0),(12,'purchase','purchase.price.history_check','下单时显示历史价格','开启后，创建采购订单时显示该物料的历史采购价格','switch',NULL,'true',NULL,60,NULL,NULL,'2026-03-02 16:36:02',0),(13,'production','production.wo.auto_no','工单号自动生成','开启后创建工单时自动生成工单号','switch',NULL,'true',NULL,10,NULL,NULL,'2026-03-02 16:36:02',0),(14,'production','production.scheduling.mode','排程方式','选择生产排程的默认方式','radio','[{\"label\": \"手动排程\", \"value\": \"manual\"}, {\"label\": \"按交期自动排程\", \"value\": \"auto_deadline\"}, {\"label\": \"按产能自动排程\", \"value\": \"auto_capacity\"}]','manual',NULL,20,NULL,NULL,'2026-03-02 16:36:02',0),(15,'production','production.wo.over_produce_ratio','工单超产比例（%）','允许实际生产数量超出工单计划数量的最大比例','number',NULL,'5',NULL,30,NULL,NULL,'2026-03-02 16:36:02',0),(16,'production','production.material.issue_mode','领料方式','工单领料的默认处理方式','radio','[{\"label\": \"手动领料\", \"value\": \"manual\"}, {\"label\": \"按工单自动备料\", \"value\": \"auto_by_wo\"}]','manual',NULL,40,NULL,NULL,'2026-03-02 16:36:02',0),(17,'production','production.wo.auto_stock_in','完工自动入库','开启后，工单完工时自动生成成品入库任务','switch',NULL,'false','true',50,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(18,'production','production.task.need_qc','工序完工需质检','开启后，每道工序完工后须通过质检才能继续下道工序','switch',NULL,'false','true',60,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(19,'production','production.wo.allow_multi_shift','允许跨班次生产','开启后，一张工单可以跨不同班次进行生产','switch',NULL,'true',NULL,70,NULL,NULL,'2026-03-02 16:36:02',0),(20,'workreport','workreport.need_approval','报工需要审批','开启后，员工报工记录须经班组长或主管审批','switch',NULL,'false',NULL,10,NULL,NULL,'2026-03-02 16:36:02',0),(21,'workreport','workreport.allow_cross_team','允许跨班组报工','开启后，员工可以对不属于自己班组的工单进行报工','switch',NULL,'false','true',20,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(22,'workreport','workreport.allow_over_qty','允许超工单数量报工','开启后，报工累计数量可以超过工单计划数量','switch',NULL,'false',NULL,30,NULL,NULL,'2026-03-02 16:36:02',0),(23,'workreport','workreport.exception.notify','异常上报通知渠道','工人提交异常上报时，系统通过以下渠道发送通知','checkbox','[{\"label\": \"系统消息\", \"value\": \"system\"}, {\"label\": \"短信\", \"value\": \"sms\"}, {\"label\": \"邮件\", \"value\": \"email\"}]','system',NULL,40,NULL,NULL,'2026-03-02 16:36:02',0),(24,'workreport','workreport.wage.calc_mode','工资计算方式','报工后工资结算的默认计算方式','radio','[{\"label\": \"按工时计算\", \"value\": \"by_hours\"}, {\"label\": \"按件计算\", \"value\": \"by_piece\"}, {\"label\": \"固定工资\", \"value\": \"fixed\"}]','by_hours',NULL,50,NULL,NULL,'2026-03-02 16:36:02',0),(25,'workreport','workreport.exception.auto_pause','异常上报自动暂停工单','开启后，工人上报异常后对应工单自动暂停直到异常处理完毕','switch',NULL,'false',NULL,60,NULL,NULL,'2026-03-02 16:36:02',0),(26,'warehouse','warehouse.inout.need_approval','出入库需要审批','开启后，出入库申请须经审批后才能执行入库或出库操作','switch',NULL,'false','true',10,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(27,'warehouse','warehouse.alert.mode','库存预警方式','选择库存不足时的预警监控维度','radio','[{\"label\": \"按物料预警（全局）\", \"value\": \"by_material\"}, {\"label\": \"按库位预警（分仓）\", \"value\": \"by_location\"}]','by_material',NULL,20,NULL,NULL,'2026-03-02 16:36:02',0),(28,'warehouse','warehouse.alert.enable_notify','启用库存预警通知','开启后，当库存低于安全库存时发送预警通知','switch',NULL,'true',NULL,30,NULL,NULL,'2026-03-02 16:36:02',0),(29,'warehouse','warehouse.in.auto_label','入库自动生成标签','开启后，物料入库时自动生成并打印库存标签','switch',NULL,'false',NULL,40,NULL,NULL,'2026-03-02 16:36:02',0),(30,'warehouse','warehouse.enable_fifo','启用先进先出（FIFO）','开启后，出库时系统按照物料入库时间顺序进行出库','switch',NULL,'false','true',50,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(31,'warehouse','warehouse.allow_negative','允许负库存','开启后，库存不足时仍允许出库（库存会显示为负数）','switch',NULL,'false',NULL,60,NULL,NULL,'2026-03-02 16:36:02',0),(32,'warehouse','warehouse.out.need_review','出库需要复核','开启后，出库操作完成后须由仓管员进行复核确认','switch',NULL,'false',NULL,70,NULL,NULL,'2026-03-02 16:36:02',0),(33,'quality','quality.incoming.enable','启用来料检验（IQC）','开启后，采购到货须经来料检验方可入库','switch',NULL,'false','true',10,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(34,'quality','quality.process.enable','启用过程检验（IPQC）','开启后，生产工序间须进行过程质量检验','switch',NULL,'false','true',20,'1','2026-03-02 17:20:13','2026-03-02 16:36:02',0),(35,'quality','quality.outgoing.enable','启用出货检验（OQC）','开启后，产品发货前须通过出货检验','switch',NU