    -- ----------------------------------------------------------------------
    -- BOM 版本激活默认审批流 (由 BomApprovalFlowInitializer 同样在启动时兜底)
    -- 使用 WHERE NOT EXISTS 保证幂等、不依赖硬编码主键
    -- ----------------------------------------------------------------------
    INSERT INTO `biz_approval_flow` (`flow_name`, `flow_code`, `business_type`, `enabled`, `remark`, `create_time`, `update_time`, `deleted`)
    SELECT 'BOM 版本激活审批', 'FLOW_BOM_ACTIVATE', 'bom_version_activation', 1, 'BOM 版本激活时触发,由管理员审批', NOW(), NOW(), 0
    WHERE NOT EXISTS (SELECT 1 FROM `biz_approval_flow` WHERE `flow_code` = 'FLOW_BOM_ACTIVATE');

    INSERT INTO `biz_approval_node` (`flow_id`, `node_name`, `node_order`, `approval_mode`, `create_time`, `update_time`, `deleted`)
    SELECT f.`id`, '管理员审批', 1, 'OR', NOW(), NOW(), 0
    FROM `biz_approval_flow` f
    WHERE f.`flow_code` = 'FLOW_BOM_ACTIVATE'
      AND NOT EXISTS (
          SELECT 1 FROM `biz_approval_node` n WHERE n.`flow_id` = f.`id` AND n.`node_order` = 1
      );

    INSERT INTO `biz_approval_node_approver` (`node_id`, `approver_type`, `approver_id`)
    SELECT n.`id`, 'role', r.`id`
    FROM `biz_approval_node` n
    JOIN `biz_approval_flow` f ON f.`id` = n.`flow_id`
    JOIN `sys_role` r ON r.`role_code` = 'admin'
    WHERE f.`flow_code` = 'FLOW_BOM_ACTIVATE'
      AND n.`node_order` = 1
      AND NOT EXISTS (
          SELECT 1 FROM `biz_approval_node_approver` a
          WHERE a.`node_id` = n.`id` AND a.`approver_type` = 'role' AND a.`approver_id` = r.`id`
      );

    -- ============================================================
    -- EAM 设备管理菜单（位于 基础数据 之后、财务成本 之前）
    -- 先将 sort_order >= 10 的顶级菜单整体 +1 腾出位置
    -- ============================================================
    UPDATE sys_menu SET sort_order = sort_order + 1 WHERE parent_id = 0 AND sort_order >= 10 AND deleted = 0;

